import { describe, expect, it } from "vitest";
import { createApp, type App } from "../src/app.ts";
import { RedemptionRepository } from "../src/repositories/redemptionRepository.ts";

const NOW = "2026-10-01T08:00:00Z";
const fixedClock = () => new Date(NOW);

function createOrder(app: App, amountCents: number): number {
  const res = app.request("POST", "/orders", { customer: "alice", amountCents });
  return (res.body as { id: number }).id;
}

function createCoupon(app: App, input: Record<string, unknown>): void {
  const res = app.request("POST", "/coupons", {
    code: "SAVE20",
    type: "PERCENT",
    value: 20,
    validFrom: "2026-01-01T00:00:00Z",
    validUntil: "2027-01-01T00:00:00Z",
    ...input,
  });
  expect(res.status).toBe(201);
}

function apply(app: App, id: number, body: unknown) {
  return app.request("POST", `/orders/${id}/apply-coupon`, body);
}

function redemptionCount(app: App): number {
  return (app.db.prepare("SELECT COUNT(*) AS c FROM coupon_redemptions").get() as { c: number }).c;
}

describe("apply-coupon: discount calculation", () => {
  it("AC-01: PERCENT 20 on 10000", () => {
    const app = createApp({ clock: fixedClock });
    createCoupon(app, { code: "SAVE20", type: "PERCENT", value: 20 });
    const id = createOrder(app, 10000);
    const res = apply(app, id, { couponCode: "SAVE20" });
    expect(res.status).toBe(200);
    expect(res.body).toMatchObject({ discountCents: 2000, finalAmountCents: 8000, couponCode: "SAVE20" });
  });

  it("AC-02: FIXED 1500 on 10000", () => {
    const app = createApp({ clock: fixedClock });
    createCoupon(app, { code: "FIXED15", type: "FIXED", value: 1500 });
    const id = createOrder(app, 10000);
    const res = apply(app, id, { couponCode: "FIXED15" });
    expect(res.body).toMatchObject({ discountCents: 1500, finalAmountCents: 8500 });
  });

  it("AC-03: PERCENT 20 capped at 5000", () => {
    const app = createApp({ clock: fixedClock });
    createCoupon(app, { code: "CAP20", type: "PERCENT", value: 20, maxDiscountCents: 5000 });
    const id = createOrder(app, 100000);
    const res = apply(app, id, { couponCode: "CAP20" });
    expect(res.body).toMatchObject({ discountCents: 5000, finalAmountCents: 95000 });
  });

  it("AC-04: FIXED larger than order is clamped to the amount", () => {
    const app = createApp({ clock: fixedClock });
    createCoupon(app, { code: "BIG", type: "FIXED", value: 3000 });
    const id = createOrder(app, 1000);
    const res = apply(app, id, { couponCode: "BIG" });
    expect(res.body).toMatchObject({ discountCents: 1000, finalAmountCents: 0 });
  });

  it("AC-05: PERCENT rounds down", () => {
    const app = createApp({ clock: fixedClock });
    createCoupon(app, { code: "PCT15", type: "PERCENT", value: 15 });
    const id = createOrder(app, 999);
    const res = apply(app, id, { couponCode: "PCT15" });
    expect(res.body).toMatchObject({ discountCents: 149, finalAmountCents: 850 });
  });

  it("AC-06: amount equal to the minimum is allowed", () => {
    const app = createApp({ clock: fixedClock });
    createCoupon(app, { code: "MIN5", type: "FIXED", value: 100, minAmountCents: 5000 });
    const id = createOrder(app, 5000);
    expect(apply(app, id, { couponCode: "MIN5" }).status).toBe(200);
  });
});

describe("apply-coupon: code normalization", () => {
  it("AC-10: trims and uppercases the code", () => {
    const app = createApp({ clock: fixedClock });
    createCoupon(app, { code: "SAVE20", type: "PERCENT", value: 20 });
    const id = createOrder(app, 10000);
    const res = apply(app, id, { couponCode: "  save20  " });
    expect(res.status).toBe(200);
    expect(res.body).toMatchObject({ couponCode: "SAVE20" });
  });
});

describe("apply-coupon: validity window", () => {
  it("AC-07: now equal to validFrom is accepted", () => {
    const app = createApp({ clock: fixedClock });
    createCoupon(app, {
      code: "START",
      type: "FIXED",
      value: 100,
      validFrom: NOW,
      validUntil: "2026-12-01T00:00:00Z",
    });
    const id = createOrder(app, 10000);
    expect(apply(app, id, { couponCode: "START" }).status).toBe(200);
  });

  it("AC-07: now equal to validUntil is expired", () => {
    const app = createApp({ clock: fixedClock });
    createCoupon(app, {
      code: "END",
      type: "FIXED",
      value: 100,
      validFrom: "2026-01-01T00:00:00Z",
      validUntil: NOW,
    });
    const id = createOrder(app, 10000);
    const res = apply(app, id, { couponCode: "END" });
    expect(res.status).toBe(400);
    expect((res.body as any).error.code).toBe("COUPON_EXPIRED");
  });
});

describe("apply-coupon: persistence", () => {
  it("AC-09: updates the order, adds a redemption row and increments used_count", () => {
    const app = createApp({ clock: fixedClock });
    createCoupon(app, { code: "SAVE20", type: "PERCENT", value: 20 });
    const id = createOrder(app, 10000);
    apply(app, id, { couponCode: "SAVE20" });

    expect(app.request("GET", `/orders/${id}`).body).toMatchObject({
      discountCents: 2000,
      finalAmountCents: 8000,
      couponCode: "SAVE20",
    });
    expect(redemptionCount(app)).toBe(1);
    expect(app.request("GET", "/coupons/SAVE20").body).toMatchObject({ usedCount: 1 });
  });

  it("rolls back the whole redemption when a write fails", () => {
    const app = createApp({ clock: fixedClock });
    createCoupon(app, { code: "SAVE20", type: "PERCENT", value: 20 });
    const repo = new RedemptionRepository(app.db);

    expect(() => repo.apply(999, "SAVE20", 2000, NOW)).toThrow();

    expect(redemptionCount(app)).toBe(0);
    expect(app.request("GET", "/coupons/SAVE20").body).toMatchObject({ usedCount: 0 });
  });
});

describe("apply-coupon: errors and precedence", () => {
  it("AC-08: a second coupon is rejected and the order is unchanged", () => {
    const app = createApp({ clock: fixedClock });
    createCoupon(app, { code: "SAVE20", type: "PERCENT", value: 20 });
    const id = createOrder(app, 10000);
    apply(app, id, { couponCode: "SAVE20" });

    const res = apply(app, id, { couponCode: "SAVE20" });
    expect(res.status).toBe(409);
    expect((res.body as any).error.code).toBe("COUPON_ALREADY_APPLIED");
    expect(app.request("GET", `/orders/${id}`).body).toMatchObject({
      discountCents: 2000,
      finalAmountCents: 8000,
      couponCode: "SAVE20",
    });
  });

  it("rejects an invalid body", () => {
    const app = createApp({ clock: fixedClock });
    const id = createOrder(app, 10000);
    for (const body of [{}, { couponCode: 123 }, { couponCode: "   " }, { couponCode: null }]) {
      const res = apply(app, id, body);
      expect(res.status).toBe(400);
      expect((res.body as any).error.code).toBe("INVALID_REQUEST");
    }
  });

  it("rejects an unknown order", () => {
    const app = createApp({ clock: fixedClock });
    const res = apply(app, 999, { couponCode: "SAVE20" });
    expect(res.status).toBe(404);
    expect((res.body as any).error.code).toBe("ORDER_NOT_FOUND");
  });

  it("rejects a non-pending order", () => {
    const app = createApp({ clock: fixedClock });
    createCoupon(app, { code: "SAVE20", type: "PERCENT", value: 20 });
    const id = createOrder(app, 10000);
    app.request("POST", `/orders/${id}/pay`);
    const res = apply(app, id, { couponCode: "SAVE20" });
    expect(res.status).toBe(409);
    expect((res.body as any).error.code).toBe("ORDER_NOT_PENDING");
  });

  it("rejects an unknown coupon", () => {
    const app = createApp({ clock: fixedClock });
    const id = createOrder(app, 10000);
    const res = apply(app, id, { couponCode: "NOPE" });
    expect(res.status).toBe(404);
    expect((res.body as any).error.code).toBe("COUPON_NOT_FOUND");
  });

  it("rejects an inactive coupon", () => {
    const app = createApp({ clock: fixedClock });
    createCoupon(app, { code: "OFF", status: "DISABLED" });
    const id = createOrder(app, 10000);
    const res = apply(app, id, { couponCode: "OFF" });
    expect(res.status).toBe(400);
    expect((res.body as any).error.code).toBe("COUPON_INACTIVE");
  });

  it("rejects a coupon that is not yet valid", () => {
    const app = createApp({ clock: fixedClock });
    createCoupon(app, { code: "SOON", validFrom: "2026-12-01T00:00:00Z", validUntil: "2027-01-01T00:00:00Z" });
    const id = createOrder(app, 10000);
    const res = apply(app, id, { couponCode: "SOON" });
    expect(res.status).toBe(400);
    expect((res.body as any).error.code).toBe("COUPON_NOT_YET_VALID");
  });

  it("rejects an exhausted coupon", () => {
    const app = createApp({ clock: fixedClock });
    createCoupon(app, { code: "ONCE", usageLimit: 1 });
    const first = createOrder(app, 10000);
    apply(app, first, { couponCode: "ONCE" });
    const second = createOrder(app, 10000);
    const res = apply(app, second, { couponCode: "ONCE" });
    expect(res.status).toBe(400);
    expect((res.body as any).error.code).toBe("COUPON_USAGE_EXHAUSTED");
  });

  it("rejects an order below the minimum", () => {
    const app = createApp({ clock: fixedClock });
    createCoupon(app, { code: "MIN", minAmountCents: 20000 });
    const id = createOrder(app, 10000);
    const res = apply(app, id, { couponCode: "MIN" });
    expect(res.status).toBe(400);
    expect((res.body as any).error.code).toBe("MINIMUM_NOT_MET");
  });

  it("checks the body before the order, and the order before the coupon", () => {
    const app = createApp({ clock: fixedClock });

    const invalid = apply(app, 999, {});
    expect((invalid.body as any).error.code).toBe("INVALID_REQUEST");

    const id = createOrder(app, 10000);
    app.request("POST", `/orders/${id}/cancel`);
    const notPending = apply(app, id, { couponCode: "NOPE" });
    expect((notPending.body as any).error.code).toBe("ORDER_NOT_PENDING");
  });

  it("leaves the database unchanged on rejection", () => {
    const app = createApp({ clock: fixedClock });
    createCoupon(app, { code: "MIN", minAmountCents: 20000 });
    const id = createOrder(app, 10000);
    apply(app, id, { couponCode: "MIN" });

    expect(redemptionCount(app)).toBe(0);
    expect(app.request("GET", "/coupons/MIN").body).toMatchObject({ usedCount: 0 });
    expect(app.request("GET", `/orders/${id}`).body).toMatchObject({
      discountCents: 0,
      finalAmountCents: 10000,
      couponCode: null,
      status: "PENDING",
    });
  });
});

describe("apply-coupon: response shape", () => {
  it("AC-14: the response body equals GET /orders/:id", () => {
    const app = createApp({ clock: fixedClock });
    createCoupon(app, { code: "SAVE20", type: "PERCENT", value: 20 });
    const id = createOrder(app, 10000);
    const applied = apply(app, id, { couponCode: "SAVE20" });
    const fetched = app.request("GET", `/orders/${id}`);
    expect(applied.body).toEqual(fetched.body);
  });
});

